#include <functional>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> layout(const std::string& text, int boxWidth, int maxLines,
                                const std::function<int(const std::string&)>& measure)
{
    return {text};
}

int main()
{
    auto measure{[](const std::string& s) { return static_cast<int>(s.size()) * 8; }};
    for (const auto& line : layout("The quick brown fox jumps over the lazy dog again and again", 120, 3, measure))
        std::cout << line << '\n';
}
